import { IsoDateString } from './api-response';
import { IntegrationJobStatus } from './enums';

// Credentials this system uses to call the webshop (`/stores/:id/integration-credentials`)

export type StoreCredentialsStatus = {
    configured: boolean;
    apiKeyHint: string | null;
    updatedAt: IsoDateString | null;
    webhookPath: string;
};

/** `webhookSecret` is only returned when it was generated by the server. */
export type StoreCredentialsSetResult = StoreCredentialsStatus & {
    webhookSecret?: string;
};

export type SetStoreCredentials = {
    apiKey?: string;
    apiSecret: string;
    webhookSecret?: string;
};

// Integration jobs (`/stores/:id/jobs`)

export type IntegrationJob = {
    id: string;
    status: IntegrationJobStatus;
    productId: string | null;
    payload: unknown;
    result: unknown;
    attempts: number;
    runAfter: IsoDateString;
    lastError: string | null;
    createdAt: IsoDateString;
    finishedAt: IsoDateString | null;
};

export type JobListQuery = {
    status?: IntegrationJobStatus;
    limit?: number;
};

// Product sync

/** Raw mapping record returned after syncing one product to a store. */
export type ChannelMapping = {
    id: string;
    productId: string;
    storeInstanceId: string;
    externalProductId: string;
    externalUrl: string | null;
    lastSyncedAt: IsoDateString | null;
};

export type SyncFailure = {
    productId: string;
    sku: string;
    error: string;
};

export type SyncAllResult = {
    total: number;
    synced: number;
    failed: SyncFailure[];
};

// Wholesaler catalog import

export type CatalogImportFailure = {
    sku: string;
    ean: string;
    error: string;
};

export type CatalogImportResult = {
    total: number;
    created: number;
    updated: number;
    zeroed: number;
    failed: CatalogImportFailure[];
};
